const tests=[{id:1,title:'N5 模擬試験（もぎしけん）',vocab:21,grammar:22,listening:24},{id:2,title:'N5 模擬試験（もぎしけん）',vocab:20,grammar:23,listening:24},{id:3,title:'N5 模擬試験（もぎしけん）',vocab:22,grammar:21,listening:25}];
const questions={vocab:[{jp:'毎朝（まいあさ）、六時（ろくじ）に＿＿。',en:'Every morning, I ___ at six o’clock.',opts:['おきます','ねます','たべます','のみます'],answer:0},{jp:'この本（ほん）は＿＿ですか。',en:'How much is this book?',opts:['いくら','どこ','だれ','いつ'],answer:0}],grammar:[{jp:'私（わたし）は日本語（にほんご）＿＿勉強（べんきょう）します。',en:'I study Japanese.',opts:['を','に','で','が'],answer:0},{jp:'昨日（きのう）、学校（がっこう）＿＿行（い）きませんでした。',en:'Yesterday, I did not go to school.',opts:['へ','を','が','も'],answer:0}],listening:[{jp:'音声（おんせい）を聞（き）いて、正（ただ）しい答（こた）えを選（えら）んでください。',en:'Listen and choose the correct answer.',opts:['七時（しちじ）','八時（はちじ）','九時（くじ）','十時（じゅうじ）'],answer:1}]};
const app=document.querySelector('#app');let currentQuestion=null,translationShown=false,examMode=false,currentType='random',currentSet=1,timerInterval=null,remainingSeconds=0;
function nav(active=''){return `<header class="topbar"><div class="shell nav"><button class="brand nav-btn" onclick="navigate('home')"><span class="mark">日</span><span>japanesenx</span></button><nav class="links always-visible"><button class="nav-btn ${active==='practice'?'active':''}" onclick="navigate('practice')">Practice</button><button class="nav-btn ${active==='tests'?'active':''}" onclick="navigate('tests')">Test</button><button class="nav-btn ${active==='login'?'active':''}" onclick="navigate('login')">Login</button><button class="nav-btn ${active==='about'?'active':''}" onclick="navigate('about')">About us</button></nav></div></header>`}
function layout(active,content){app.innerHTML=`${nav(active)}<main>${content}</main><footer><div class="shell footer-in"><span>© 2026 Japanesenx</span><span>Made for 日本語（にほんご） learners</span></div></footer>`;window.scrollTo(0,0)}
function pageHero(kicker,title,copy){return `<section class="page-hero shell"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="lead">${copy}</p></section>`}
function home(){layout('',`<section class="shell hero"><div><div class="eyebrow">JLPT N5 · 日本語能力試験</div><h1>Small steps.<br><span>Big fluency.</span></h1><p class="lead">Focused Japanese practice and true-to-format mock exams, built to make N5 preparation feel clear, calm, and achievable.</p><div class="actions"><button class="primary" onclick="navigate('practice')">Start practicing</button><button class="secondary" onclick="navigate('tests')">Explore mock tests</button></div></div><div class="hero-art"><div class="sun"></div><div class="paper"><div class="paper-lines"><i></i><i></i></div><div class="paper-kanji">学</div><div class="paper-lines"><i></i><i></i><i></i></div><div class="stamp">合格</div></div><div class="scribble">毎日すこしずつ</div></div></section><div class="shell stats"><div class="stat"><strong>3 practice modes</strong><span>Train one skill at a time</span></div><div class="stat"><strong>90 minutes</strong><span>Full N5 exam simulation</span></div><div class="stat"><strong>ふりがな</strong><span>Read every kanji with confidence</span></div></div><section class="shell home-choice"><article><div class="eyebrow">Practice</div><h2>Learn without pressure.</h2><p>Random questions, instant feedback, and optional English translations.</p><button class="text-link static-link" onclick="navigate('practice')">Open practice →</button></article><article><div class="eyebrow">Test</div><h2>Know where you stand.</h2><p>Timed N5 papers that recreate the exam experience.</p><button class="text-link static-link" onclick="navigate('tests')">View test papers →</button></article></section>`)}
function practicePage(){layout('practice',`${pageHero('Daily training · 練習（れんしゅう）','Practice your weak spots.','Choose a skill and get a random question from any active N5 paper. English translation is available here when you need it.')}<section class="shell section page-section"><div class="section-head"><div><h2>Choose a practice mode</h2><p>Low-pressure study with immediate feedback.</p></div><div class="level-switch"><button class="active">N5</button><button disabled>N4</button><button disabled>N3</button><button disabled>N2</button><button disabled>N1</button></div></div><div class="practice-grid"><article class="practice-card" data-jp="語"><div class="iconbox">あ</div><h3>Vocabulary</h3><div class="jp-label">語彙（ごい）</div><p>Build confidence with words, kanji readings, and meaning in context.</p><button class="text-link" onclick="openPractice('vocab')">Practice randomly →</button></article><article class="practice-card" data-jp="文"><div class="iconbox">文</div><h3>Grammar & Reading</h3><div class="jp-label">文法（ぶんぽう）・読解（どっかい）</div><p>Master particles, sentence patterns, and short reading passages.</p><button class="text-link" onclick="openPractice('grammar')">Practice randomly →</button></article><article class="practice-card" data-jp="聴"><div class="iconbox">♫</div><h3>Listening</h3><div class="jp-label">聴解（ちょうかい）</div><p>Train your ear for everyday conversations and key information.</p><button class="text-link" onclick="openPractice('listening')">Practice randomly →</button></article></div><div class="practice-random"><div><b>Mix everything · おまかせ</b><p>A surprise question from any N5 set and section.</p></div><button class="primary" onclick="openPractice('random')">Shuffle a question ↻</button></div></section>`)}
function testCards(){return tests.map(t=>`<article class="test-card"><div class="test-top"><div><span class="setno">SET ${String(t.id).padStart(2,'0')}</span><h3>${t.title}</h3></div><span class="pill">90 min</span></div><div class="score-row"><span>Vocabulary · 語彙（ごい）</span><b>— / ${t.vocab}</b></div><div class="score-row"><span>Grammar & Reading</span><b>— / ${t.grammar}</b></div><div class="score-row"><span>Listening · 聴解（ちょうかい）</span><b>— / ${t.listening}</b></div><button class="details-btn" onclick="openTest(${t.id})">View paper →</button></article>`).join('')}
function testsPage(){layout('tests',`<section class="tests-page">${pageHero('Timed papers · 模擬試験（もぎしけん）','N5 mock tests','Take one section or complete the full paper in 90 minutes.')}<section class="shell section page-section"><div class="section-head"><div><h2>Available papers</h2><p>Sets update automatically as new papers are added.</p></div><div class="level-switch"><button class="active">N5</button><button disabled>N4</button><button disabled>N3</button><button disabled>N2</button><button disabled>N1</button></div></div><div class="test-grid">${testCards()}</div></section></section>`)}
function aboutPage(){layout('about',`${pageHero('Our approach · 私（わたし）たち','Less guessing. More growing.','A calmer, more focused way to prepare for the Japanese Language Proficiency Test.')}<section class="shell section page-section"><div class="about"><div><h2>Built for steady progress.</h2></div><div class="about-copy"><p>Japanesenx pairs realistic exam papers with low-pressure daily practice, so learners can understand mistakes and build durable confidence.</p><div class="principles"><div class="principle"><b>Kanji, made readable</b><small>Every kanji includes its hiragana reading.</small></div><div class="principle"><b>Two distinct modes</b><small>Helpful translations in practice, pure exam conditions in tests.</small></div><div class="principle"><b>Dynamic paper sets</b><small>New tests appear as they are added to the collection.</small></div><div class="principle"><b>Progress that stays</b><small>Sign in to keep your personal best scores.</small></div></div></div></div></section>`)}
function loginPage(){layout('login',`${pageHero('Your account · アカウント','Save your best scores.','Sign in to keep your test history and personal best for every paper.')}<section class="shell section auth-page"><form class="login-form login-card" onsubmit="fakeLogin(event)"><label>Email<input type="email" required placeholder="you@example.com"></label><label>Password<input type="password" required minlength="6" placeholder="At least 6 characters"></label><div class="notice">Demo sign-in: this prototype stores your session in this browser only.</div><button class="primary" type="submit">Login</button></form></section>`)}
function modal(body){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="modal" onclick="if(event.target===this)closeModal()"><div class="modal">${body}</div></div>`)}
function closeModal(){document.querySelector('#modal')?.remove()}
function pick(type){const pool=type==='random'?Object.values(questions).flat():questions[type];return pool[Math.floor(Math.random()*pool.length)]}
function openPractice(type){stopTimer();examMode=false;currentType=type;currentQuestion=pick(type);translationShown=false;location.hash='practice-question';renderRoute()}
function questionPage(){if(!currentQuestion){navigate(examMode?'tests':'practice');return}const title=currentType==='random'?'Random mix':currentType==='vocab'?'Vocabulary':currentType==='grammar'?'Grammar & Reading':'Listening';layout(examMode?'tests':'practice',`<section class="question-page"><div class="shell question-shell"><div class="question-toolbar"><button class="back-link" onclick="leaveQuestion()">← ${examMode?'Back to test papers':'Back to practice'}</button>${examMode?'<div class="timer" aria-live="polite"><span>Time remaining</span><strong id="timerDisplay">'+formatTime(remainingSeconds)+'</strong></div>':'<span class="practice-badge">Practice mode</span>'}</div><article class="question-panel"><div class="question-progress"><span>${examMode?`N5 MOCK TEST · SET ${currentSet}`:'N5 QUICK PRACTICE'}</span><span>Question 01</span></div><h1>${title}</h1><div class="question-meta">${examMode?'Choose the best answer':'Question from all active sets'}</div>${currentType==='listening'?'<button class="secondary audio-button" onclick="speakQuestion()">▶ Play audio</button>':''}<div class="question question-large">${currentQuestion.jp}</div>${examMode?'':`<div class="translation ${translationShown?'':'hidden'}" id="translation">${currentQuestion.en}</div><button class="secondary reveal-button" onclick="revealTranslation()">${translationShown?'Hide':'Reveal'} in English</button>`}<div class="options question-options">${currentQuestion.opts.map((o,i)=>`<button class="option" onclick="answer(${i})"><b>${i+1}.</b> ${o}</button>`).join('')}</div><div class="question-footer"><span>${examMode?'Your answer is recorded automatically.':'Take your time. There is no timer in practice.'}</span><button class="primary" onclick="nextQuestion()">${examMode?'Next question →':'Skip / Next question →'}</button></div></article></div></section>`);if(examMode)paintTimer()}
function nextQuestion(){currentQuestion=pick(currentType);translationShown=false;questionPage()}
function revealTranslation(){if(examMode)return;translationShown=!translationShown;document.querySelector('#translation').classList.toggle('hidden',!translationShown);event.currentTarget.textContent=`${translationShown?'Hide':'Reveal'} in English`}
function answer(i){if(examMode){toast('Answer recorded');setTimeout(nextQuestion,450);return}const right=i===currentQuestion.answer;toast(right?'正解（せいかい）！ Correct 🎉':'もう一度（いちど）。 Try again.');if(right)setTimeout(nextQuestion,650)}
function speakQuestion(){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(currentQuestion.jp.replace(/（.*?）/g,''));u.lang='ja-JP';speechSynthesis.speak(u)}}
function openTest(id){const t=tests.find(x=>x.id===id);modal(`<div class="modal-head"><div><div class="eyebrow">Set ${String(id).padStart(2,'0')}</div><h2>${t.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><p style="color:var(--muted);line-height:1.7">Choose one section, or sit the complete 90-minute paper. Your highest score is saved when you’re logged in.</p><div class="options"><button class="option" onclick="startTest('vocab',${id})"><b>Vocabulary · 語彙（ごい）</b><br><small>${t.vocab} questions · 20 minutes</small></button><button class="option" onclick="startTest('grammar',${id})"><b>Grammar & Reading</b><br><small>${t.grammar} questions · 40 minutes</small></button><button class="option" onclick="startTest('listening',${id})"><b>Listening · 聴解（ちょうかい）</b><br><small>${t.listening} questions · 30 minutes</small></button></div><button class="primary" style="width:100%" onclick="startTest('random',${id})">Start full 90-minute test →</button>`)}
function startTest(type,id){closeModal();stopTimer();examMode=true;currentType=type;currentSet=id;currentQuestion=pick(type);translationShown=false;remainingSeconds=({vocab:20,grammar:40,listening:30,random:90}[type]||90)*60;location.hash='test-question';renderRoute();startTimer()}
function startTimer(){stopTimer();timerInterval=setInterval(()=>{remainingSeconds=Math.max(0,remainingSeconds-1);paintTimer();if(remainingSeconds===0){stopTimer();toast('Time is up. Your test has been submitted.');setTimeout(()=>navigate('tests'),1200)}},1000)}
function stopTimer(){if(timerInterval){clearInterval(timerInterval);timerInterval=null}}
function formatTime(total){const m=Math.floor(total/60),s=total%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function paintTimer(){const el=document.querySelector('#timerDisplay');if(el){el.textContent=formatTime(remainingSeconds);el.classList.toggle('timer-warning',remainingSeconds<300)}}
function leaveQuestion(){stopTimer();navigate(examMode?'tests':'practice')}
function fakeLogin(e){e.preventDefault();localStorage.setItem('jnx-user','Learner');toast('おかえりなさい！ Welcome back.');setTimeout(()=>navigate('tests'),700)}
function navigate(page){if(!page.includes('question'))stopTimer();location.hash=page==='home'?'':page;renderRoute()}
function renderRoute(){const route=location.hash.slice(1)||'home';({home,practice:practicePage,tests:testsPage,login:loginPage,about:aboutPage,'practice-question':questionPage,'test-question':questionPage}[route]||home)()}
function toast(msg){document.querySelector('.toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">${msg}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2300)}
window.addEventListener('hashchange',renderRoute);renderRoute();
